import re

def extract_final_number(response: str) -> int | None:
    matches = re.findall(r'-?\d+', response)
    if matches:
        try:
            return int(matches[-1])
        except:
            return None
    return None

def reward(response: str) -> float:
    num = extract_final_number(response)
    if num is None:
        return 0.0
    return 1.0 if num % 2 == 0 else 0.0
